const {nplTransform}=require('./transform.js');const assert=require('node:assert/strict');
let passed=0;function test(name,fn){fn();++passed;console.log('PASS '+name);}
const prefix='NPL-Dual-62d910 / ';
const base={mode:'global',secret:'FAKE-TEST-SECRET',dns:{enable:true,'proxy-server-nameserver':['1.1.1.1']},tun:{enable:true},proxies:[{name:'TIM',type:'vmess',server:'example.invalid',port:443,uuid:'fake-test-credential',udp:true,'ws-opts':{path:'/a'}}], 'proxy-groups':[{name:'Existing',type:'select',proxies:['TIM','DIRECT']}],rules:['DOMAIN,existing.invalid,Existing','MATCH,DIRECT'],'proxy-providers':{original:{type:'http',url:'https://example.invalid/sub?fake=token',override:{udp:true}}}};
const plan={schema:1,ethernet:'以太网',wifi:'WLAN',ethernetGuid:'eth-guid',wifiGuid:'wifi-guid',nodes:['TIM'],apps:[{match:'PROCESS-PATH',value:'C:\\Games\\game.exe',target:'ethernet'},{match:'PROCESS-NAME',value:'ai.exe',target:'wifi'},{match:'PROCESS-NAME',value:'default.exe',target:'system'}]};
const copy=x=>JSON.parse(JSON.stringify(x));const output=nplTransform(base,plan);
test('Rule mode',()=>assert.equal(output.mode,'rule'));
test('process resolution requested',()=>assert.equal(output['find-process-mode'],'always'));
test('no global interface override',()=>assert.equal(output['interface-name'],undefined));
test('campus direct supports UDP and dual stack',()=>assert.deepEqual(output.proxies[0],{name:prefix+'Campus Direct',type:'direct',udp:true,'ip-version':'dual','interface-name':'以太网'}));
test('proxy clone bound to Wi-Fi',()=>assert.equal(output.proxies[1]['interface-name'],'WLAN'));
test('original node and credentials unchanged',()=>assert.deepEqual(output.proxies.slice(2),base.proxies));
test('cloned protocol parameters unchanged',()=>{let n=copy(output.proxies[1]);n.name='TIM';delete n['interface-name'];assert.deepEqual(n,base.proxies[0]);});
test('no hidden mutation of input',()=>assert.equal(base.mode,'global'));
test('old groups unchanged',()=>assert.deepEqual(output['proxy-groups'].slice(1),base['proxy-groups']));
test('old rules retained in order',()=>assert.deepEqual(output.rules.slice(2),base.rules));
test('process rules precede old MATCH/domain rules',()=>assert.match(output.rules[0],/^PROCESS-PATH,/));
test('system default emits no new rule',()=>assert.equal(output.rules.some(x=>x.includes('default.exe')),false));
test('DNS preserved, not claimed protected',()=>assert.deepEqual(output.dns,base.dns));
test('TUN preserved',()=>assert.deepEqual(output.tun,base.tun));
test('provider subscription/override preserved',()=>assert.deepEqual(output['proxy-providers'],base['proxy-providers']));
test('protected selection has no DIRECT/unbound originals',()=>assert.deepEqual(output['proxy-groups'][0].proxies,[prefix+'Wi-Fi / TIM','REJECT']));
test('missing selected node becomes REJECT-only',()=>{let b=copy(base);b.proxies=[];assert.deepEqual(nplTransform(b,plan)['proxy-groups'][0].proxies,['REJECT']);});
test('chain bypass is excluded',()=>{let b=copy(base);b.proxies[0]['dialer-proxy']='Existing';assert.deepEqual(nplTransform(b,plan)['proxy-groups'][0].proxies,['REJECT']);});
test('MPTCP node excluded',()=>{let b=copy(base);b.proxies[0].mptcp=true;assert.deepEqual(nplTransform(b,plan)['proxy-groups'][0].proxies,['REJECT']);});
test('unknown protocol excluded',()=>{let b=copy(base);b.proxies[0].type='future';assert.deepEqual(nplTransform(b,plan)['proxy-groups'][0].proxies,['REJECT']);});
test('subscription refresh retains rules while using new protocol fields',()=>{let b=copy(base);b.proxies[0].uuid='updated-fake';let r=nplTransform(b,plan);assert.equal(r.proxies[1].uuid,'updated-fake');assert.deepEqual(r.rules,output.rules);});
test('repeated raw-source generation is deterministic',()=>assert.deepEqual(nplTransform(base,plan),output));
test('no silent stacking onto already transformed runtime',()=>assert.throws(()=>nplTransform(output,plan)));
test('existing global interface rejected',()=>assert.throws(()=>nplTransform({...base,'interface-name':'Other'},plan)));
test('same target interfaces rejected',()=>assert.throws(()=>nplTransform(base,{...plan,wifi:plan.ethernet})));
test('same GUID rejected',()=>assert.throws(()=>nplTransform(base,{...plan,wifiGuid:plan.ethernetGuid})));
test('comma rule injection rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[{match:'PROCESS-NAME',value:'x.exe,DIRECT',target:'wifi'}]})));
test('newline injection rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[{match:'PROCESS-NAME',value:'x.exe\n',target:'wifi'}]})));
test('UNC path rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[{match:'PROCESS-PATH',value:'\\\\server\\x.exe',target:'wifi'}]})));
test('traversal rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[{match:'PROCESS-PATH',value:'C:\\a\\..\\x.exe',target:'wifi'}]})));
test('duplicate process policy rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[plan.apps[0],plan.apps[0]]})));
test('duplicate node selection rejected',()=>assert.throws(()=>nplTransform(base,{...plan,nodes:['TIM','TIM']})));
test('malformed groups rejected',()=>assert.throws(()=>nplTransform({...base,'proxy-groups':{}},plan)));
test('empty scope rejected',()=>assert.throws(()=>nplTransform(base,{...plan,apps:[]})));
test('rejected transformation leaves original config untouched',()=>{const before=JSON.stringify(base);assert.throws(()=>nplTransform(base,{...plan,apps:[plan.apps[0],plan.apps[0]]}));assert.equal(JSON.stringify(base),before);});
console.log(`Transform tests: ${passed} passed, 0 failed. No live network/configuration writes.`);
